@StateBacked(MutableStateContainer(scope = #instance))
define class Counter as
    state {
        let int count = 0;
    }
    increment() -> int ::
        return handle_state(critical-write |s| -> {
            s.count += 1;
            return s.count;
        });
    end
    get_count() -> int ::
        return handle_state(critical-read |s| -> s.count);
    end
end

pub routine main(): void {
    let Counter counter = new Counter();
    counter.increment();
    stdio.stdout.write(counter.increment());
    return;
}

define state_container SessionState as
    state { let int requests = 0; }
    request_count() -> int ::
        return handle_state(critical-read |s| -> s.requests);
    end
end

@Inject(SessionState, scope = #instance)
define class SessionManager as
    get_requests() -> int ::
        return self.session_state.request_count();
    end
end

pub routine main(): void {
    let SessionManager manager = new SessionManager();
    stdio.stdout.write(manager.get_requests());
    return;
}

